// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ShibaMoon {
    function owner() external view returns (address);
    function excludeFromFee(address account) external;
    function isExcludedFromFee(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf7958ffc6cE46dE09e0AB69B7dA360C38b16266B;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll directly tamper with storage
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Calculate the storage slot for _owner (slot 0 in Ownable)
        bytes32 ownerSlot = bytes32(uint256(0));

        // Store our address in the owner slot
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Verify we are now the owner
        address currentOwner = ShibaMoon(TARGET).owner();
        require(currentOwner == attacker, "Failed to become owner");

        // Demonstrate owner privilege by calling an owner-only function
        // Let's try to exclude ourselves from fees as proof
        vm.prank(attacker);
        ShibaMoon(TARGET).excludeFromFee(attacker);

        // Verify we are excluded from fees
        bool isExcluded = ShibaMoon(TARGET).isExcludedFromFee(attacker);
        require(isExcluded, "Failed to exclude from fee - not really owner");
        assertEq(currentOwner, attacker, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
